create table if not exists public.economy_accounts (user_id uuid primary key references auth.users(id) on delete cascade, xp integer not null default 0 check (xp >= 0 and xp <= 10000), coins bigint not null default 0 check (coins >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.economy_transactions (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, asset text not null check (asset in ('xp','coins')), amount bigint not null check (amount <> 0), kind text not null check (kind in ('earn','spend','refund','admin_adjustment')), source text not null, idempotency_key text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(user_id,idempotency_key,asset));
create table if not exists public.reward_definitions (code text primary key, label text not null, xp integer not null default 0 check (xp >= 0), coins bigint not null default 0 check (coins >= 0), active boolean not null default true, repeatable boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.reward_claims (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, reward_code text not null references public.reward_definitions(code), claim_key text not null, created_at timestamptz not null default now(), unique(user_id,claim_key));
create table if not exists public.inventory_items (code text primary key, name text not null, category text not null, coin_price bigint not null default 0 check (coin_price >= 0), active boolean not null default true, metadata jsonb not null default '{}'::jsonb);
create table if not exists public.inventory (user_id uuid not null references auth.users(id) on delete cascade, item_code text not null references public.inventory_items(code), quantity integer not null default 1 check (quantity > 0), acquired_at timestamptz not null default now(), primary key(user_id,item_code));
create index if not exists economy_transactions_user_created_idx on public.economy_transactions(user_id,created_at desc);
